mapper.select:
SELECT password_hash
FROM sys_user_password_history
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
ORDER BY changed_time DESC, id DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO sys_user_password_history (
    tenant_id, user_id, password_hash, changed_time,
    create_time, update_time
) VALUES (
    #{tenantId}, #{userId}, #{passwordHash}, #{changedTime},
    #{changedTime}, #{changedTime}
)

mapper.delete:
DELETE FROM sys_user_password_history
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id NOT IN (
      SELECT retained.id
      FROM (
          SELECT id
          FROM sys_user_password_history
          WHERE tenant_id = #{tenantId}
            AND user_id = #{userId}
          ORDER BY changed_time DESC, id DESC
          LIMIT #{retainCount}
      ) retained
  )

DELETE FROM sys_user_password_history
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
